<script lang="ts">import StatusBadge from './StatusBadge.svelte'; export let game:any; export let onNavigate:(x:string)=>void=()=>{}; export let onRefresh:()=>void=()=>{}; async function upload(e:Event){const f=(e.currentTarget as HTMLInputElement).files?.[0];if(!f)return;const form=new FormData();form.append('file',f);await fetch('/api/games/'+game.id+'/rulebook',{method:'POST',body:form});onRefresh()}</script>
{#if game}<section class="page"><a href="/" on:click|preventDefault={()=>onNavigate('/')}>← Collection</a><div class="head"><div><h1>{game.title}</h1><StatusBadge state={game.pipeline_state}/></div><div class="actions"><button class="primary" disabled={!game.has_published_content} on:click={async()=>{const r=await fetch('/api/sessions?game_id='+game.id,{method:'POST'});const s=await r.json();onNavigate('/session/'+s.id)}}>Start session</button><a class="button" href={'/games/'+game.id+'/preview'}>Preview</a></div></div><p class="muted">{game.error_message||'Manage the authoritative Rulebook and local Content.'}</p><div class="panel"><h2>Rulebook</h2><input type="file" accept=".pdf" on:change={upload}/>{#if game.rulebook}<a class="button" href={'/games/'+game.id+'/pdf'}>View rulebook</a>{/if}</div><div class="panel"><h2>Content</h2>{#if game.has_draft_content}<a class="button" href={'/games/'+game.id+'/review'}>Review draft</a>{/if}<button class="primary" disabled={!game.rulebook?.has_extracted_text} on:click={async()=>{if(!confirm('Generate content using the configured cloud provider?'))return;await fetch('/api/games/'+game.id+'/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:'{"confirm":true}'});onRefresh()}}>Generate content</button></div><button class="danger" on:click={async()=>{if(confirm('Delete this game? This cannot be undone.')){await fetch('/api/games/'+game.id,{method:'DELETE'});onNavigate('/')}}}>Delete game</button></section>{:else}<section class="page"><p>Game not found.</p></section>{/if}
<style>.page{max-width:1000px;margin:auto;padding:32px}.head{display:flex;justify-content:space-between;gap:16px;align-items:center;margin:24px 0}.head h1{font-size:32px;margin:0 0 10px}.actions{display:flex;gap:8px;flex-wrap:wrap}.panel{background:#1e1c27;border:1px solid #29263c;border-radius:16px;padding:20px;margin:20px 0;display:flex;gap:16px;align-items:center;flex-wrap:wrap}.primary,.button,.danger{padding:10px 20px;border-radius:10px;text-decoration:none;cursor:pointer}.primary{background:#a277ff;color:#15141b;border:0}.primary:disabled{opacity:.45}.button{border:1px solid #29263c}.danger{background:transparent;color:#ff6767;border:1px solid #ff676755}.muted{color:#6d6d6d}@media(max-width:767px){.page{padding:20px}.head{flex-direction:column;align-items:flex-start}}</style>
